import{_ as c,V as i,W as l,X as u,Z as n,a1 as s,$ as a,a0 as d,Y as e,F as p}from"./framework-b1bd8911.js";const k={},r=n("h1",{id:"图片自动裁剪",tabindex:"-1"},[n("a",{class:"header-anchor",href:"#图片自动裁剪","aria-hidden":"true"},"#"),s(" 图片自动裁剪")],-1),m=n("blockquote",null,[n("p",null,[s("本文介绍 "),n("code",null,"image-plugin"),s(" 中的图片自动裁剪能力，对应的包为 "),n("code",null,"com.github.hui.quick.plugin.image.wrapper.split")])],-1),v=n("p",null,'在开始之前，先定一个小目标：手上有一张美术同学给的"素材聚合图"——一整张大图上密密麻麻摆了几十个游戏道具图标，间距随意、大小不一，我们希望程序自动把这张大图裁成一张张独立的小图。',-1),g=e(`<div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>大图（透明背景）：
+-------------------------------------+
|  [图标A]      [图标B]   [图标C]      |
|         [图标D]                     |
|   [图标E]         [图标F] [图标G]    |
+-------------------------------------+

裁剪后：
out/A_1.png, A_2.png, ... 每个图标一个小文件
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这就是 <code>ImgSplitWrapper</code> 要干的事。对应 README 里写的：&quot;自动实现大资源图，裁剪为一个一个的小图&quot;。</p><h3 id="i-场景与设计思路" tabindex="-1"><a class="header-anchor" href="#i-场景与设计思路" aria-hidden="true">#</a> I. 场景与设计思路</h3><blockquote><p>关键词：<strong>不按网格切，按内容切</strong></p></blockquote><p>传统的雪碧图切割工具，要求素材是等间距等尺寸的网格排列，切法就是固定行列。但现实中的聚合图往往是美术随手摆的，间距不均匀，甚至图标大小都不一样，网格切法直接歇菜。</p><p><code>image-plugin</code> 的思路是：</p><ol><li><strong>背景判定</strong>：传入一个 <code>Predicate&lt;Integer&gt;</code>（入参是像素的 int 颜色值，返回 true 表示这是背景色），默认判定是&quot;透明像素即背景&quot;。这一步把图片分成&quot;内容&quot;和&quot;背景&quot;两类点</li><li><strong>找边界点</strong>：从左上角开始逐行扫描，找到第一个不是背景的点</li><li><strong>边框扫描</strong>：以这个点为起点，沿着上/下/左/右/四个斜角共 8 个方向扩散，凡是&quot;自身不是背景点、且 8 邻域里有背景点&quot;的点都算边界点，一路记录上下左右四个极值，直到扫不出新点为止——这一圈下来，就得到了这个图案的外接矩形</li><li><strong>裁剪 + 抹除</strong>：按外接矩形把这块区域拷贝成一张新图；同时把原图上这块区域全部置为透明，防止下一轮又扫到它</li><li><strong>循环</strong>：回到第 2 步继续找下一个图案，直到整张图全是背景色</li></ol><p>所以它裁出来的不是&quot;格子&quot;，而是&quot;图案&quot;——每个图案一张图，天然不重叠，也不依赖排列规律。</p><h3 id="ii-依赖引入" tabindex="-1"><a class="header-anchor" href="#ii-依赖引入" aria-hidden="true">#</a> II. 依赖引入</h3><div class="language-xml line-numbers-mode" data-ext="xml"><pre class="language-xml"><code><span class="token comment">&lt;!-- https://mvnrepository.com/artifact/com.github.liuyueyi.media/image-plugin --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>dependency</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>groupId</span><span class="token punctuation">&gt;</span></span>com.github.liuyueyi.media<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>groupId</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>artifactId</span><span class="token punctuation">&gt;</span></span>image-plugin<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>artifactId</span><span class="token punctuation">&gt;</span></span>
    <span class="token comment">&lt;!-- 请使用最新版本号替换下面的版本 --&gt;</span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>version</span><span class="token punctuation">&gt;</span></span>3.1.0<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>version</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>dependency</span><span class="token punctuation">&gt;</span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="iii-使用示例" tabindex="-1"><a class="header-anchor" href="#iii-使用示例" aria-hidden="true">#</a> III. 使用示例</h3>`,11),b={href:"https://github.com/liuyueyi/quick-media/blob/master/plugins/image-plugin/src/test/java/com/github/hui/quick/plugin/test/feat/split/ImgSplitTest.java",target:"_blank",rel:"noopener noreferrer"},h=e(`<h4 id="_1-透明背景的素材大图-默认背景判定" tabindex="-1"><a class="header-anchor" href="#_1-透明背景的素材大图-默认背景判定" aria-hidden="true">#</a> 1. 透明背景的素材大图（默认背景判定）</h4><p>最省事的姿势，什么都不用配，透明色自动当背景：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@Test</span>
<span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">split</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">IOException</span> <span class="token punctuation">{</span>
    <span class="token keyword">try</span> <span class="token punctuation">{</span>
        <span class="token comment">// 一张透明背景的素材聚合图，请替换为你自己的文件</span>
        <span class="token class-name">String</span> img <span class="token operator">=</span> <span class="token string">&quot;D:\\\\quick-media\\\\resource\\\\assets\\\\bundle_item_icon\\\\img\\\\2766150e-9c1a-4025-b652-5b0d6b7b3fa9.e792b.png&quot;</span><span class="token punctuation">;</span>
        <span class="token class-name">ImgSplitWrapper</span><span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">setImg</span><span class="token punctuation">(</span>img<span class="token punctuation">)</span>
                <span class="token comment">// 裁剪后保存图片的路径</span>
                <span class="token punctuation">.</span><span class="token function">setOutputPath</span><span class="token punctuation">(</span><span class="token string">&quot;d:/quick-media/items/e792b&quot;</span><span class="token punctuation">)</span>
                <span class="token comment">// 裁剪后图片名前缀</span>
                <span class="token punctuation">.</span><span class="token function">setOutputImgName</span><span class="token punctuation">(</span><span class="token string">&quot;e792b&quot;</span><span class="token punctuation">)</span>
                <span class="token comment">// 输出文件名为 前缀_序号.png，这个参数控制起始序号，默认从 0 开始</span>
                <span class="token punctuation">.</span><span class="token function">setOutputIncrIndex</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">splitAndSave</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;over&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span> <span class="token keyword">catch</span> <span class="token punctuation">(</span><span class="token class-name">Exception</span> e<span class="token punctuation">)</span> <span class="token punctuation">{</span>
        e<span class="token punctuation">.</span><span class="token function">printStackTrace</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>输出结果就是 <code>d:/quick-media/items/e792b/e792b_1.png</code>、<code>e792b_2.png</code>……每个图案一个文件。</p><h4 id="_2-白底大图-自定义背景判定" tabindex="-1"><a class="header-anchor" href="#_2-白底大图-自定义背景判定" aria-hidden="true">#</a> 2. 白底大图（自定义背景判定）</h4><p>如果不透明背景（比如白色），默认判定就失效了，需要自己给 <code>bgPredicate</code>：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@Test</span>
<span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">split2</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">IOException</span> <span class="token punctuation">{</span>
    <span class="token keyword">try</span> <span class="token punctuation">{</span>
        <span class="token class-name">String</span> img <span class="token operator">=</span> <span class="token string">&quot;http://cdn.hhui.top/git/quick-media/futu.jpg&quot;</span><span class="token punctuation">;</span>
        <span class="token class-name">ImgSplitWrapper</span><span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">setImg</span><span class="token punctuation">(</span>img<span class="token punctuation">)</span>
                <span class="token comment">// 裁剪后保存图片的路径</span>
                <span class="token punctuation">.</span><span class="token function">setOutputPath</span><span class="token punctuation">(</span><span class="token string">&quot;d:/quick-media/&quot;</span><span class="token punctuation">)</span>
                <span class="token comment">// 裁剪后图片名</span>
                <span class="token punctuation">.</span><span class="token function">setOutputImgName</span><span class="token punctuation">(</span><span class="token string">&quot;tu&quot;</span><span class="token punctuation">)</span>
                <span class="token comment">// 上面这个图会裁剪成4个图，生成的图片分别为 tu_1, tu_2, tu_3 等，下面这个参数则控制的是文件名中的序号</span>
<span class="token comment">//                    .setOutputIncrIndex(1)</span>
                <span class="token comment">// 用于指定图片中哪些颜色为背景色</span>
                <span class="token punctuation">.</span><span class="token function">setBgPredicate</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">Predicate</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">Integer</span><span class="token punctuation">&gt;</span></span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
                    <span class="token annotation punctuation">@Override</span>
                    <span class="token keyword">public</span> <span class="token keyword">boolean</span> <span class="token function">test</span><span class="token punctuation">(</span><span class="token class-name">Integer</span> rgb<span class="token punctuation">)</span> <span class="token punctuation">{</span>
                        <span class="token class-name">Color</span> color <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Color</span><span class="token punctuation">(</span>rgb<span class="token punctuation">,</span> <span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                        <span class="token comment">// 透明的地方当作背景，白色系认为是背景</span>
                        <span class="token keyword">return</span> color<span class="token punctuation">.</span><span class="token function">getAlpha</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">&lt;=</span> <span class="token number">10</span> <span class="token operator">||</span> color<span class="token punctuation">.</span><span class="token function">getRed</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">&gt;=</span> <span class="token number">220</span> <span class="token operator">&amp;&amp;</span> color<span class="token punctuation">.</span><span class="token function">getGreen</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">&gt;=</span> <span class="token number">220</span> <span class="token operator">&amp;&amp;</span> color<span class="token punctuation">.</span><span class="token function">getBlue</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">&gt;=</span> <span class="token number">220</span><span class="token punctuation">;</span>
                    <span class="token punctuation">}</span>
                <span class="token punctuation">}</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">splitAndSave</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;over&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span> <span class="token keyword">catch</span> <span class="token punctuation">(</span><span class="token class-name">Exception</span> e<span class="token punctuation">)</span> <span class="token punctuation">{</span>
        e<span class="token punctuation">.</span><span class="token function">printStackTrace</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这个判定式的意思是：alpha 小于等于 10 的（透明）算背景；R/G/B 都大于等于 220 的（接近白色的浅色）也算背景。阈值可以根据素材的实际情况调，比如边缘有抗锯齿的浅灰色过渡带，就把阈值放宽一点。</p><h4 id="_3-批量处理一个目录" tabindex="-1"><a class="header-anchor" href="#_3-批量处理一个目录" aria-hidden="true">#</a> 3. 批量处理一个目录</h4><p>真实项目里往往是一批聚合图要处理，测试类里就是这么干的：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@Test</span>
<span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">testSplit</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">IOException</span> <span class="token punctuation">{</span>
    <span class="token class-name">String</span> path <span class="token operator">=</span> <span class="token string">&quot;D:\\\\quick-media\\\\resource\\\\assets\\\\bundle_item_icon\\\\img&quot;</span><span class="token punctuation">;</span>
    <span class="token class-name">File</span> file <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">File</span><span class="token punctuation">(</span>path<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">int</span> i <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span>
    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token class-name">File</span> f <span class="token operator">:</span> file<span class="token punctuation">.</span><span class="token function">listFiles</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span>f<span class="token punctuation">.</span><span class="token function">getName</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">endsWith</span><span class="token punctuation">(</span><span class="token string">&quot;png&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token class-name">String</span> name <span class="token operator">=</span> f<span class="token punctuation">.</span><span class="token function">getAbsolutePath</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token class-name">String</span> out <span class="token operator">=</span> name<span class="token punctuation">.</span><span class="token function">substring</span><span class="token punctuation">(</span>name<span class="token punctuation">.</span><span class="token function">indexOf</span><span class="token punctuation">(</span><span class="token string">&quot;.&quot;</span><span class="token punctuation">)</span> <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">,</span> name<span class="token punctuation">.</span><span class="token function">lastIndexOf</span><span class="token punctuation">(</span><span class="token string">&quot;.&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

            <span class="token keyword">try</span> <span class="token punctuation">{</span>
                <span class="token class-name">ImgSplitWrapper</span><span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">setImg</span><span class="token punctuation">(</span>name<span class="token punctuation">)</span>
                        <span class="token punctuation">.</span><span class="token function">setOutputPath</span><span class="token punctuation">(</span><span class="token string">&quot;d:/quick-media/items/&quot;</span> <span class="token operator">+</span> out<span class="token punctuation">)</span>
                        <span class="token punctuation">.</span><span class="token function">setOutputImgName</span><span class="token punctuation">(</span>out<span class="token punctuation">)</span>
                        <span class="token punctuation">.</span><span class="token function">setOutputIncrIndex</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span>
                        <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
                        <span class="token punctuation">.</span><span class="token function">splitAndSave</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token punctuation">}</span> <span class="token keyword">catch</span> <span class="token punctuation">(</span><span class="token class-name">Exception</span> e<span class="token punctuation">)</span> <span class="token punctuation">{</span>
                e<span class="token punctuation">.</span><span class="token function">printStackTrace</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token punctuation">}</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="_4-不落盘-直接拿裁剪结果" tabindex="-1"><a class="header-anchor" href="#_4-不落盘-直接拿裁剪结果" aria-hidden="true">#</a> 4. 不落盘，直接拿裁剪结果</h4><p>如果后续还想自己加工（加水印、改尺寸、上传 OSS 之类），用 <code>split2imgs()</code> 拿内存中的 <code>List&lt;BufferedImage&gt;</code> 即可，不会写任何文件：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">BufferedImage</span><span class="token punctuation">&gt;</span></span> imgs <span class="token operator">=</span> <span class="token class-name">ImgSplitWrapper</span><span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">setImg</span><span class="token punctuation">(</span><span class="token string">&quot;tu.png&quot;</span><span class="token punctuation">)</span> <span class="token comment">// 请替换</span>
        <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">split2imgs</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="iv-参数说明" tabindex="-1"><a class="header-anchor" href="#iv-参数说明" aria-hidden="true">#</a> IV. 参数说明</h3><p><code>ImgSplitWrapper</code> 的所有参数由 <code>ImgSplitOptions</code> 承载：</p><table><thead><tr><th>参数</th><th>说明</th><th>默认值</th></tr></thead><tbody><tr><td><code>img</code></td><td>原图，支持路径（本地/http 均可）或 <code>BufferedImage</code></td><td>必传</td></tr><tr><td><code>outputPath</code></td><td>裁剪结果保存目录，目录不存在会自动创建</td><td><code>/tmp</code></td></tr><tr><td><code>outputName</code></td><td>输出文件名前缀</td><td>随机 UUID</td></tr><tr><td><code>outputIncrIndex</code></td><td>输出文件名的起始序号，文件名为 <code>前缀_序号.png</code></td><td><code>0</code></td></tr><tr><td><code>bgPredicate</code></td><td>背景色判定，入参为像素 int 颜色值，返回 true 表示是背景</td><td>alpha == 0（透明即背景）</td></tr></tbody></table><p>两个出口方法：</p><table><thead><tr><th>方法</th><th>行为</th></tr></thead><tbody><tr><td><code>splitAndSave()</code></td><td>裁剪并按上面的规则落盘，固定输出 png 格式</td></tr><tr><td><code>split2imgs()</code></td><td>只裁剪，结果留在内存里，自己爱怎么处理怎么处理</td></tr></tbody></table><h3 id="v-适用场景与注意点" tabindex="-1"><a class="header-anchor" href="#v-适用场景与注意点" aria-hidden="true">#</a> V. 适用场景与注意点</h3><p><strong>适用场景：</strong></p><ul><li>游戏素材加工：美术给的道具/装备聚合图，一键拆成单件素材</li><li>图标集拆分：设计稿里一堆零散 icon，需要拆出来入库</li><li>截图整理：把一张截图里的多个 UI 元素抠成独立小图</li></ul><p><strong>注意点：</strong></p><ol><li><strong>背景判定是整个功能的核心</strong>。<code>bgPredicate</code> 配得不准，要么整图被当成一个图案（背景没圈住），要么图案被切碎（图案内部的浅色区域被误判为背景）。判定条件建议&quot;宁紧勿松&quot;，先在测试图上跑 <code>split2imgs()</code> 看看结果再调阈值</li><li><strong>连在一起的图案分不开</strong>。边框扫描是按连通边界走的，两个图案如果在像素上紧挨着（8 邻域连通），会被当成一个整体裁出来。要求拆分的话，素材之间至少要留一像素的背景带</li><li><strong>输出的外接矩形可能是空的</strong>。如果某个&quot;图案&quot;其实宽高为 0（比如一个孤立的背景判定歧义点），会自动跳过，不会产出 0×0 的文件</li><li><strong>落盘固定是 png</strong>。<code>splitAndSave()</code> 内部写死了 <code>ImageIO.write(bi, &quot;png&quot;, ...)</code>，透明通道不会丢；jpg 源图裁出来也建议存 png</li><li><strong>性能与图的大小成正比</strong>。每拆一个图案都要重新扫一遍全图找起点，大图（比如 4K 素材图）会比较慢，属于一次性加工场景，跑批不用太在意，别放进实时接口就好</li><li><strong>默认输出路径是 <code>/tmp</code></strong>。Windows 下这个路径不一定存在，用 <code>splitAndSave()</code> 前记得显式 <code>setOutputPath</code>，免得文件写到意想不到的地方</li></ol><h3 id="vi-其他" tabindex="-1"><a class="header-anchor" href="#vi-其他" aria-hidden="true">#</a> VI. 其他</h3><p><strong>项目地址：</strong></p>`,26),f={href:"https://github.com/liuyueyi/quick-media",target:"_blank",rel:"noopener noreferrer"},_=n("li",null,[n("code",null,"QuickMedia"),s(" 目标是创建一个专注图文，音视频，二维码处理的开源项目")],-1),q=n("p",null,[n("strong",null,"系列相关文章：")],-1),I=n("code",null,"bgPredicate",-1);function y(x,w){const t=p("ExternalLinkIcon"),o=p("RouterLink");return i(),l("div",null,[r,m,v,u(" more "),g,n("blockquote",null,[n("p",null,[s("以下代码取自源码测试类 "),n("a",b,[s("ImgSplitTest.java"),a(t)])])]),h,n("ul",null,[n("li",null,[n("a",f,[s("https://github.com/liuyueyi/quick-media"),a(t)])]),_]),q,n("ul",null,[n("li",null,[a(o,{to:"/git/quick-media/image/10.%E5%9B%BE%E7%89%87%E5%83%8F%E7%B4%A0%E5%8C%96%E4%BD%BF%E7%94%A8%E7%A4%BA%E4%BE%8B.html"},{default:d(()=>[s("10.图片像素化使用示例")]),_:1}),s("："),I,s(" 背景判定同样出现在像素化模块里，设计是一脉相承的")])])])}const E=c(k,[["render",y],["__file","13.图片自动裁剪.html.vue"]]);export{E as default};
